// Catatan: join read-only ke users (dimiliki modul identity) dipakai untuk
// menampilkan nama/email guru/wali kelas tanpa N+1 call lintas modul. Semua
// TULIS ke users/memberships/sessions/invitations tetap lewat IdentityGateway
// (consumer-side interface), tidak pernah lewat query di sini.
func (q *Queries) ListStudents(ctx context.Context, arg ListStudentsParams) ([]ListStudentsRow, error) {
	rows, err := q.db.Query(ctx, listStudents,
		arg.AcademicYearID,
		arg.SchoolID,
		arg.Q,
		arg.ClassID,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStudentsRow
	for rows.Next() {
		var i ListStudentsRow
		if err := rows.Scan(
			&i.ID,
			&i.Nis,
			&i.Nisn,
			&i.Name,
			&i.Gender,
			&i.BirthDate,
			&i.Status,
			&i.ClassID,
			&i.ClassName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

