const listTeachers = `-- name: ListTeachers :many
SELECT t.id, t.school_id, t.user_id, t.nip, u.name AS user_name, u.email AS user_email
FROM teachers t JOIN users u ON u.id = t.user_id
WHERE t.school_id = $1
ORDER BY u.name
`

