const upsertEnrollment = `-- name: UpsertEnrollment :one

INSERT INTO enrollments (school_id, student_id, class_id)
VALUES ($1, $2, $3)
ON CONFLICT (student_id, class_id) DO UPDATE SET class_id = EXCLUDED.class_id
RETURNING id, school_id, student_id, class_id, created_at
`

type UpsertEnrollmentParams struct {
	SchoolID  int64 `json:"school_id"`
	StudentID int64 `json:"student_id"`
	ClassID   int64 `json:"class_id"`
}

// -- enrollments --
func (q *Queries) UpsertEnrollment(ctx context.Context, arg UpsertEnrollmentParams) (Enrollment, error) {
	row := q.db.QueryRow(ctx, upsertEnrollment, arg.SchoolID, arg.StudentID, arg.ClassID)
	var i Enrollment
	err := row.Scan(
		&i.ID,
		&i.SchoolID,
		&i.StudentID,
		&i.ClassID,
		&i.CreatedAt,
	)
	return i, err
}
